@startuml

class Product {
  + name : string
  + description : string
  + netPrice : double
}

class Country {
  + name : string
  + vatRate : float
  + currency : string
  + conversionRateToEuro : float
}

class Manufacturer {
  + name : string
}

class Representative {
  + firstName : string
  + lastName : string
  + socialSecurityNumber : string
  + telephone : string
  + email : string
}

class Customer {
  + name : string
  + address : string
  + telephone : string
  + email : string
}

class Order {
  + orderId : string
  + quantity : int
  + orderDate : date
  + desiredDeliveryDate : date
}

Product "*" -- "1" Manufacturer : manufacturedBy
Product "*" -- "1" Country : availableIn
Representative "1" -- "1" Country : responsibleFor
Representative "1" -- "0..*" Order : places
Customer "1" -- "0..*" Order : places
Order "*" -- "1" Product : refersTo
Customer "*" -- "0..*" Country : resellsIn

@enduml

